style.css:
@-moz-document domain("colegia.org") {
/* 1. FORCE BACKGROUND PINK */
    body, #root, .main-container, .dashboard-wrapper, [class*="content"] {
        background-color: #F4C2C2 !important; 
    }

    /* 2. SIDEBARS & MENUS */
    nav, .sidebar, .header, [class*="nav"], [class*="menu"] {
        background-color: #FFD1DC !important; 
    }

    /* 3. ICON FIX (TARGETS NAVY BLUE) */
    /* This shifts blue icons into a pinkish-red hue */
    img, svg, i, [class*="icon"], .fas, .far, .material-icons {
        filter: invert(72%) sepia(21%) saturate(763%) hue-rotate(305deg) brightness(98%) contrast(92%) !important;
    }

    /* 4. TEXT COLORS (DARK PINK) */
    * {
        color: #B24C63 !important; /* Deeper pink for contrast */
    }

    /* 5. WHITE CARDS & BOXES */
    .card, .container, .box, [class*="item"], [class*="card"] {
        background-color: #ffffff !important;
        border: 2px solid #FFD1DC !important;
        border-radius: 12px !important;
    }

    /* 6. BUTTONS */
    button, .btn, [role="button"] {
        background-color: #D87093 !important;
        color: white !important;
        border: none !important;
    }
}
